from collections import Counter

def transform(grid):
    h = len(grid)
    w = len(grid[0])
    bh, bw = 3, 3
    out = []
    for br in range(h // bh):
        row = []
        for bc in range(w // bw):
            cnt = Counter()
            for i in range(br * bh, br * bh + bh):
                for j in range(bc * bw, bc * bw + bw):
                    c = grid[i][j]
                    if c != 5:
                        cnt[c] += 1
            if cnt:
                best = max(cnt.items(), key=lambda kv: (kv[1], -kv[0]))[0]
            else:
                best = 5
            row.append(best)
        out.append(row)
    return out
